  ('sw-evostar-80ed', 'sky-watcher', 'optik-tup', 'Evostar 80ED', 'ED camlı ikili apokromatik; 600 mm odakla hem orta boy bulutsulara hem küçük galaksilere yeter. Astrofoto için 0.85x reducer ile 510 mm f/6.4''e iner.', 'Giriş segment', 600, 80, null, null, null, null, 3.6, '{"f/":"7.5","Tip":"İkili ED","Backfocus":"55 mm"}'::jsonb, array['Reducer olmadan kadraj köşelerinde alan eğriliği görünür.', 'Odaklayıcı standart 2 inç; ağır kamera yükünde sarkma yapabilir.']::text[]),
  ('wo-zs73-iii', 'william-optics', 'optik-tup', 'ZenithStar 73 III', 'Taşınabilir 73 mm ikili APO; Flat73A düzelticisiyle tam kareye kadar düz alan verir.', 'Orta segment', 430, 73, null, null, null, null, 2.4, '{"f/":"5.9","Tip":"İkili APO","Backfocus":"55 mm"}'::jsonb, '{}'::text[]),
  ('wo-gt81-iii', 'william-optics', 'optik-tup', 'GT81 III', 'Üçlü APO camla renk hatası pratikte kaybolur; 478 mm odak geniş alanla detay arasında iyi bir orta nokta.', 'Orta segment', 478, 81, null, null, null, null, 3.6, '{"f/":"5.9","Tip":"Üçlü APO","Backfocus":"55 mm"}'::jsonb, '{}'::text[]),
  ('askar-fra600', 'askar', 'optik-tup', 'FRA600', 'Petzval tasarımı düzeltici gerektirmez: kutudan çıktığı hâliyle tam kare sensörde düz alan verir. 0.7x reducer ile 420 mm f/3.9''a iner.', 'Üst segment', 600, 108, null, null, null, null, 5.5, '{"f/":"5.6","Tip":"Beşli Petzval","Backfocus":"55 mm"}'::jsonb, array['Petzval olduğu için ayrı flattener alınmaz — toplam maliyeti düşürür.', '5.5 kg tüp, 13 kg sınıfı montür ister.']::text[]),
  ('askar-107phq', 'askar', 'optik-tup', '107PHQ', 'Dörtlü tasarım; 749 mm odakla galaksi ve küçük bulutsu hedeflerinde detay verir.', 'Üst segment', 749, 107, null, null, null, null, 6.5, '{"f/":"7","Tip":"Dörtlü APO","Backfocus":"55 mm"}'::jsonb, '{}'::text[]),
