  ('takahashi-fc100dz', 'takahashi', 'optik-tup', 'FC-100DZ', 'Florit ikili; gezegen ve çift yıldız gözlemi için keskinlik referansı. Astrofotoda reducer ile kullanılır.', 'Profesyonel', 800, 100, null, null, null, null, 4.4, '{"f/":"8","Tip":"İkili florit","Backfocus":"56 mm"}'::jsonb, '{}'::text[]),
